// Package postgres implements the finance port.Repository using pgx named args.
package postgres

import (
	"context"
	"errors"
	"fmt"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"shopnexus/internal/module/common/dbx"
	"shopnexus/internal/module/finance/domain"
	"shopnexus/internal/module/finance/port"
)

type Repo struct {
	pool *pgxpool.Pool
}

func New(pool *pgxpool.Pool) *Repo { return &Repo{pool: pool} }

var _ port.Repository = (*Repo)(nil)

// NextSessionID draws from the table's own sequence. The column is
// GENERATED BY DEFAULT AS IDENTITY precisely so the app can supply the value.
func (r *Repo) NextSessionID(ctx context.Context) (int64, error) {
	const q = `SELECT nextval(pg_get_serial_sequence('payment_session', 'id'))`
	var n int64
	if err := r.pool.QueryRow(ctx, q).Scan(&n); err != nil {
		return 0, fmt.Errorf("db next payment_session id: %w", err)
	}
	return n, nil
}

func (r *Repo) InsertSession(ctx context.Context, s *domain.Session) error {
	const q = `INSERT INTO payment_session
	               (id, kind, status, from_id, to_id, note, currency, total_amount, fx_snapshot, data, expired_at)
	           VALUES (@id, @kind, @status, @from_id, @to_id, @note, @currency, @total_amount, @fx_snapshot, @data, @expired_at)
	           RETURNING created_at`
	args := pgx.NamedArgs{
		"id":           s.ID,
		"kind":         s.Kind,
		"status":       s.Status,
		"from_id":      dbx.NullID(s.FromID),
		"to_id":        dbx.NullID(s.ToID),
		"note":         s.Note,
		"currency":     s.Currency,
		"total_amount": s.TotalAmount,
		"fx_snapshot":  dbx.NullJSON(s.FXSnapshot),
		"data":         s.Data,
		"expired_at":   s.ExpiredAt,
	}
	if err := r.pool.QueryRow(ctx, q, args).Scan(&s.CreatedAt); err != nil {
		return fmt.Errorf("db insert payment_session: %w", err)
	}
	return nil
}

func (r *Repo) FindSessionByID(ctx context.Context, id int64) (domain.Session, error) {
	const q = `SELECT id, kind, status, COALESCE(from_id, 0), COALESCE(to_id, 0), note,
	                  currency, total_amount, fx_snapshot, data, created_at, paid_at, expired_at
	           FROM payment_session WHERE id = @id`
	var s domain.Session
	err := r.pool.QueryRow(ctx, q, pgx.NamedArgs{"id": id}).Scan(
		&s.ID, &s.Kind, &s.Status, &s.FromID, &s.ToID, &s.Note,
		&s.Currency, &s.TotalAmount, &s.FXSnapshot, &s.Data, &s.CreatedAt, &s.PaidAt, &s.ExpiredAt)
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.Session{}, domain.ErrSessionNotFound
	}
	if err != nil {
		return domain.Session{}, fmt.Errorf("db scan payment_session: %w", err)
	}
	return s, nil
}

func (r *Repo) FindWallet(ctx context.Context, accountID int64, currency string) (domain.Wallet, error) {
	// Both key columns: account_id alone selects every currency the account holds.
	const q = `SELECT account_id, currency, available_balance, held_balance
	           FROM wallet WHERE account_id = @account_id AND currency = @currency`
	var w domain.Wallet
	err := r.pool.QueryRow(ctx, q, pgx.NamedArgs{"account_id": accountID, "currency": currency}).
		Scan(&w.AccountID, &w.Currency, &w.AvailableBalance, &w.HeldBalance)
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.Wallet{}, domain.ErrWalletNotFound
	}
	if err != nil {
		return domain.Wallet{}, fmt.Errorf("db scan wallet: %w", err)
	}
	return w, nil
}
